  // ------------------------------------------------------------------ 小道具
  function smooth(a, b, x) {
    var t = (x - a) / (b - a);
    t = t < 0 ? 0 : t > 1 ? 1 : t;
    return t * t * (3 - 2 * t);
  }
  function clamp(x, a, b) { return x < a ? a : x > b ? b : x; }
  // 種を決めれば毎回同じ並びになる乱数（まばたき・目の動き。撮影を再現できるようにする）
  function mulberry32(seed) {
    return function () {
      seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
      var t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  // 顔の球面に沿った変形: 中央がいちばん動き、頭の縁では動かない（輪郭は保たれる）。par は層ごとの動きの量
  function faceDisp(hd, par, x, y, yaw, pitch) {
    var R = hd.r[0], Ry = hd.r[1];
    var u = (x - hd.c[0]) / R, v = (y - hd.c[1]) / Ry;
    var uc = clamp(u, -1, 1), vc = clamp(v, -1, 1);
    var th = Math.asin(uc);
    var vv = v < -1 ? -1 : v;
    var dome = v >= 0 ? 1 : DOME + (1 - DOME) * (1 - vv * vv);          // 頭頂に近いほど動かない
    var phi = Math.asin(clamp(par * Math.sin(yaw), -1, 1)) * dome;
    var ay = clamp(-par * Ry * Math.sin(pitch), -0.5 * Ry, 0.5 * Ry);
    return [R * (Math.sin(th + phi * Math.cos(th)) - uc), ay * (1 - uc * uc) * (1 - vc * vc) * (1 - vc * vc)];
  }
