        var wr = smooth(rig.footZone[0], rig.footZone[1], y);
        wP[i] = 1 - wr;
        b1[i] = B_FOOT_A + footIdx; w1[i] = smooth(foot.ankle[1] - 6, foot.ankle[1] + 10, y);
